fn sinv(i: i32) -> i32 {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    tab[i & 31]
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let mid: i32 = h / 2;
    let amp: i32 = h / 3;
    host::display::clear(0x0a0a12);
    host::display::draw_line(0, mid, w - 1, mid, 0x303040);
    let mut i: i32 = 0;
    while i < 63 {
        let x0: i32 = i * (w - 1) / 63;
        let x1: i32 = (i + 1) * (w - 1) / 63;
        let y0: i32 = mid - sinv(i) * amp / 127;
        let y1: i32 = mid - sinv(i + 1) * amp / 127;
        host::display::draw_line(x0, y0, x1, y1, 0x00e0a0);
        i = i + 1;
    }
    host::display::draw_string(4, mid - amp - 12, "MAX", 0x808080, 1);
    host::display::draw_string(4, mid + amp + 4, "MIN", 0x808080, 1);
    host::display::present();
}
